This implementation uses `Arc<RwLock<...>>` for thread-safe access, `std::collections::HashMap` for $O(1)$ lookups, and `std::collections::VecDeque` for tracking the access order. To support "Weak References" in Rust, we use `std::sync::Weak`, which is the direct equivalent of JavaScript's `WeakRef`.

### Cargo.toml

```toml
[package]
name = "rust_lru_cache"
version = "0.1.0"
edition = "2021"

[dependencies]
tokio = { version = "1.0", features = ["full"] }
serde_json = "1.0"
```

### src/lib.rs

```rust
use std::collections::{HashMap, VecDeque};
use std::sync::{Arc, RwLock, Weak};
use std::time::{Duration, Instant};
use tokio::sync::broadcast;
use tokio::task::JoinHandle;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum EvictionReason {
    Expired,
    Lru,
    Memory,
}

pub struct CacheEntry<V> {
    pub value: Arc<V>,
    pub expires_at: Instant,
    pub size: usize,
    pub last_accessed: Instant,
    pub access_count: u64,
}

pub struct CacheStats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
    pub size: usize,
    pub memory: usize,
}

pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl: Duration,
    pub max_memory_bytes: usize,
    pub eviction_check_interval: Duration,
    pub on_evict: Option<Arc<dyn Fn(String, EvictionReason) + Send + Sync>>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl: Duration::from_secs(60),
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval: Duration::from_secs(5),
            on_evict: None,
        }
    }
}

struct Inner<V> {
    entries: HashMap<String, CacheEntry<V>>,
    access_order: VecDeque<String>,
    weak_refs: HashMap<String, Weak<V>>,
    current_memory: usize,
    stats: CacheStats,
    config: CacheConfig,
}

pub struct LRUCache<V> {
    inner: Arc<RwLock<Inner<V>>>,
    eviction_task: Arc<RwLock<Option<(JoinHandle<()>, broadcast::Sender<()>)>>>,
}

impl<V: 'static + Send + Sync> LRUCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        let inner = Inner {
            entries: HashMap::new(),
            access_order: VecDeque::new(),
            weak_refs: HashMap::new(),
            current_memory: 0,
            stats: CacheStats {
                hits: 0,
                misses: 0,
                evictions: 0,
                expirations: 0,
                size: 0,
                memory: 0,
            },
            config,
        };
        Self {
            inner: Arc::new(RwLock::new(inner)),
            eviction_task: Arc::new(RwLock::new(None)),
        }
    }

    pub fn get(&self, key: &str) -> Option<Arc<V>> {
        let mut inner = self.inner.write().unwrap();

        if let Some(entry) = inner.entries.get_mut(key) {
            if Instant::now() > entry.expires_at {
                drop(inner);
                self.delete(key, EvictionReason::Expired);
                let mut inner = self.inner.write().unwrap();
                inner.stats.misses += 1;
                return None;
            }

            entry.last_accessed = Instant::now();
            entry.access_count += 1;

            // Move to front (back of VecDeque is newest)
            let key_str = key.to_string();
            inner.access_order.retain(|k| k != &key_str);
            inner.access_order.push_back(key_str);

            inner.stats.hits += 1;
            Some(Arc::clone(&entry.value))
        } else {
            inner.stats.misses += 1;
            None
        }
    }

    pub fn put(&self, key: &str, value: V, ttl: Option<Duration>, size: Option<usize>) {
        let size = size.unwrap_or_else(|| self.estimate_size(&value));
        let ttl = ttl.unwrap_or_else(|| self.inner.read().unwrap().config.default_ttl);
        let val_arc = Arc::new(value);
        let weak_ref = Arc::downgrade(&val_arc);

        let mut inner = self.inner.write().unwrap();

        if let Some(old) = inner.entries.remove(key) {
            inner.current_memory -= old.size;
            let key_str = key.to_string();
            inner.access_order.retain(|k| k != &key_str);
        }

        while (inner.current_memory + size > inner.config.max_memory_bytes || 
               inner.entries.size() >= inner.config.max_entries) && !inner.access_order.is_empty() {
            let reason = if inner.current_memory + size > inner.config.max_memory_bytes {
                EvictionReason::Memory
            } else {
                EvictionReason::Lru
            };

            if let Some(oldest_key) = inner.access_order.pop_front() {
                if let Some(old_entry) = inner.entries.remove(&oldest_key) {
                    inner.current_memory -= old_entry.size;
                    inner.weak_refs.remove(&oldest_key);
                    inner.stats.evictions += 1;
                    if let Some(ref cb) = inner.config.on_evict {
                        cb(oldest_key, reason);
                    }
                }
            }
        }

        let entry = CacheEntry {
            value: val_arc,
            expires_at: Instant::now() + ttl,
            size,
            last_accessed: Instant::now(),
            access_count: 0,
        };

        inner.current_memory += size;
        inner.access_order.push_back(key.to_string());
        inner.weak_refs.insert(key.to_string(), weak_ref);
        inner.entries.insert(key.to_string(), entry);
    }

    pub fn delete(&self, key: &str, reason: EvictionReason) -> bool {
        let mut inner = self.inner.write().unwrap();
        if let Some(entry) = inner.entries.remove(key) {
            inner.current_memory -= entry.size;
            let key_str = key.to_string();
            inner.access_order.retain(|k| k != &key_str);
            inner.weak_refs.remove(key);

            if reason == EvictionReason::Expired {
                inner.stats.expirations += 1;
            } else {
                inner.stats.evictions += 1;
            }

            if let Some(ref cb) = inner.config.on_evict {
                cb(key.to_string(), reason);
            }
            true
        } else {
            false
        }
    }

    pub fn has(&self, key: &str) -> bool {
        let inner = self.inner.read().unwrap();
        if let Some(entry) = inner.entries.get(key) {
            if Instant::now() > entry.expires_at {
                drop(inner);
                self.delete(key, EvictionReason::Expired);
                false
            } else {
                true
            }
        } else {
            false
        }
    }

    pub fn get_stats(&self) -> CacheStats {
        let inner = self.inner.read().unwrap();
        CacheStats {
            hits: inner.stats.hits,
            misses: inner.stats.misses,
            evictions: inner.stats.evictions,
            expirations: inner.stats.expirations,
            size: inner.entries.len(),
            memory: inner.current_memory,
        }
    }

    pub fn start_eviction_loop(&self) {
        let mut task_lock = self.eviction_task.write().unwrap();
        if task_lock.is_some() { return; }

        let (tx, mut rx) = broadcast::channel(1);
        let inner_clone = Arc::clone(&self.inner);
        let interval_duration = inner_clone.read().unwrap().config.eviction_check_interval;

        let handle = tokio::spawn(async move {
            let mut interval = tokio::time::interval(interval_duration);
            loop {
                tokio::select! {
                    _ = interval.tick() => {
                        let mut expired_keys = Vec::new();
                        let mut dead_weak_keys = Vec::new();

                        {
                            let inner = inner_clone.read().unwrap();
                            let now = Instant::now();
                            for (k, e) in &inner.entries {
                                if now > e.expires_at { expired_keys.push(k.clone()); }
                            }
                            for (k, w) in &inner.weak_refs {
                                if w.strong_count() == 0 { dead_weak_keys.push(k.clone()); }
                            }
                        }

                        for k in expired_keys {
                            // Manual deletion to avoid deadlock logic
                            let mut inner = inner_clone.write().unwrap();
                            if let Some(entry) = inner.entries.remove(&k) {
                                inner.current_memory -= entry.size;
                                inner.access_order.retain(|x| x != &k);
                                inner.weak_refs.remove(&k);
                                inner.stats.expirations += 1;
                                if let Some(ref cb) = inner.config.on_evict { cb(k, EvictionReason::Expired); }
                            }
                        }

                        for k in dead_weak_keys {
                             let mut inner = inner_clone.write().unwrap();
                             if let Some(entry) = inner.entries.remove(&k) {
                                inner.current_memory -= entry.size;
                                inner.access_order.retain(|x| x != &k);
                                inner.weak_refs.remove(&k);
                                inner.stats.evictions += 1;
                                if let Some(ref cb) = inner.config.on_evict { cb(k, EvictionReason::Memory); }
                             }
                        }
                    }
                    _ = rx.recv() => break,
                }
            }
        });

        *task_lock = Some((handle, tx));
    }

    pub fn stop_eviction_loop(&self) {
        let mut task_lock = self.eviction_task.write().unwrap();
        if let Some((_, tx)) = task_lock.take() {
            let _ = tx.send(());
        }
    }

    fn estimate_size(&self, _value: &V) -> usize {
        // Rust cannot easily stringify arbitrary types to JSON at runtime without traits
        // Simplified version: 8 bytes per item for generic types
        std::mem::size_of::<V>()
    }
}
```

### src/main.rs

```rust
use rust_lru_cache::{LRUCache, CacheConfig, EvictionReason};
use std::time::Duration;
use tokio::time::sleep;
use std::sync::Arc;

#[tokio::main]
async fn main() {
    run_tests().await;
}

async fn run_tests() {
    let config = CacheConfig {
        max_entries: 3,
        default_ttl: Duration::from_millis(100),
        ..Default::default()
    };
    let cache = LRUCache::<String>::new(config);

    // Basic get/put
    cache.put("a", "hello".to_string(), None, None);
    assert_eq!(*cache.get("a").unwrap(), "hello".to_string(), "basic get");
    assert_eq!(cache.get_stats().size, 1, "size after put");

    // LRU eviction
    cache.put("b", "world".to_string(), None, None);
    cache.put("c", "foo".to_string(), None, None);
    cache.put("d", "bar".to_string(), None, None); // should evict 'a'
    assert!(!cache.has("a"), "lru eviction");
    assert!(cache.has("d"), "newest kept");

    // TTL expiration
    let cache_ttl = LRUCache::<String>::new(CacheConfig {
        max_entries: 10,
        default_ttl: Duration::from_millis(50),
        ..Default::default()
    });
    cache_ttl.put("x", "temp".to_string(), Some(Duration::from_millis(50)), None);
    sleep(Duration::from_millis(80)).await;
    assert!(cache_ttl.get("x").is_none(), "ttl expired");

    // Access order
    let cache_order = LRUCache::<String>::new(CacheConfig {
        max_entries: 3,
        ..Default::default()
    });
    cache_order.put("1", "one".to_string(), None, None);
    cache_order.put("2", "two".to_string(), None, None);
    cache_order.put("3", "three".to_string(), None, None);
    cache_order.get("1"); // access '1', making '2' the LRU
    cache_order.put("4", "four".to_string(), None, None); // should evict '2'
    assert!(!cache_order.has("2"), "access order eviction");
    assert!(cache_order.has("1"), "accessed item kept");

    // Stats
    let stats = cache_order.get_stats();
    assert!(stats.hits > 0, "has hits");
    assert!(stats.misses > 0, "has misses");

    // Eviction loop
    let cache_loop = LRUCache::<String>::new(CacheConfig {
        max_entries: 10,
        default_ttl: Duration::from_millis(50),
        eviction_check_interval: Duration::from_millis(30),
        ..Default::default()
    });
    cache_loop.put("e1", "val1".to_string(), None, None);
    cache_loop.start_eviction_loop();
    sleep(Duration::from_millis(150)).await;
    assert!(!cache_loop.has("e1"), "eviction loop cleared expired");
    cache_loop.stop_eviction_loop();

    println!("All tests passed");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_cache_logic() {
        run_tests().await;
    }
}
```

### Key Differences & Implementations:
1.  **Memory Management**: In TS, `WeakRef` is used for GC collection. In Rust, we use `std::sync::Weak`. When an `Arc` is handed out via `get()`, it increments the reference count. The "Dead Weak Ref" check in the eviction loop simulates the memory-pressure eviction found in the TS version.
2.  **Concurrency**: Instead of a single-threaded JS loop, we use `RwLock` for thread-safe access and `tokio::spawn` for the background eviction task.
3.  **Hot Path**: The `get` method returns an `Arc<V>`, which is a pointer-copy rather than a full `.clone()` of the data, satisfying the requirement to avoid clones on the hot path.
4.  **Time**: `Instant` is used instead of `Date.now()` as it is monotonic and more precise for cache TTLs.
